class Solution {
  public boolean isMatch(String s, String p) {
    int n = p.length(), m = s.length();
    boolean[][] dp = new boolean[n + 1][m + 1]; // dp[i][j]: p[0..i) matches s[0..j)
    dp[0][0] = true;
    for (int i = 1; i <= n && p.charAt(i - 1) == '*'; i++) dp[i][0] = true;
    for (int i = 1; i <= n; i++) {
      char c = p.charAt(i - 1);
      for (int j = 1; j <= m; j++) {
        if (c == '*') dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
        else if (c == '?' || c == s.charAt(j - 1)) dp[i][j] = dp[i - 1][j - 1];
      }
    }
    return dp[n][m];
  }
}
